import React, { useState, useEffect } from 'react';
import { Bars3Icon, XMarkIcon, PhoneIcon } from '@heroicons/react/24/outline';
import { useOrder } from '../context/OrderContext';

const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const { openModal } = useOrder();

  const navigation = [
    { name: 'О компании', href: '#about' },
    { name: 'Преимущества', href: '#benefits' },
    { name: 'Каталог', href: '#catalog' },
    { name: 'Отзывы', href: '#reviews' },
    { name: 'Контакты', href: '#contacts' },
  ];

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full top-0 z-50 transition-all duration-300 ${
      isScrolled 
        ? 'bg-[#121212]/95 backdrop-blur-md shadow-lg shadow-[#FF7A0020]' 
        : 'bg-transparent'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Логотип */}
          <div className="flex items-center">
            <h1 className="text-xl font-bold bg-gradient-to-r from-[#FF7A00] to-[#FFA447] bg-clip-text text-transparent">
              PhoneAccessories
            </h1>
          </div>
          
          {/* Десктопное меню */}
          <div className="hidden md:flex space-x-8">
            {navigation.map((item) => (
              <a
                key={item.name}
                href={item.href}
                className="text-[#F5F5F5] hover:text-[#FF7A00] transition-colors duration-300 font-medium"
              >
                {item.name}
              </a>
            ))}
          </div>

          {/* Контакты и CTA */}
          <div className="hidden md:flex items-center space-x-4">
            <a 
              href="tel:+79001234567" 
              className="flex items-center text-[#FF7A00] font-semibold hover:text-[#FFA447] transition-colors"
            >
              <PhoneIcon className="h-4 w-4 mr-1" />
              +7 (900) 123-45-67
            </a>
            <button
              onClick={() => openModal()}
              className="bg-gradient-to-r from-[#FF7A00] to-[#FFA447] text-white px-6 py-2 rounded-2xl font-semibold hover:shadow-lg hover:shadow-[#FF7A0040] transition-all duration-300 transform hover:scale-105"
            >
              Заказать звонок
            </button>
          </div>

          {/* Мобильное меню */}
          <div className="md:hidden">
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="text-[#F5F5F5] hover:text-[#FF7A00] transition-colors"
            >
              {isMenuOpen ? (
                <XMarkIcon className="h-6 w-6" />
              ) : (
                <Bars3Icon className="h-6 w-6" />
              )}
            </button>
          </div>
        </div>

        {/* Мобильное выпадающее меню */}
        {isMenuOpen && (
          <div className="md:hidden bg-[#1E1B1B] border-t border-[#FF7A00]/20">
            <div className="px-2 pt-2 pb-3 space-y-1">
              {navigation.map((item) => (
                <a
                  key={item.name}
                  href={item.href}
                  className="block px-3 py-2 text-[#F5F5F5] hover:text-[#FF7A00] hover:bg-[#FF7A00]/10 rounded-lg transition-all"
                  onClick={() => setIsMenuOpen(false)}
                >
                  {item.name}
                </a>
              ))}
              <div className="px-3 py-2 space-y-2">
                <a 
                  href="tel:+79001234567" 
                  className="flex items-center text-[#FF7A00] font-semibold"
                >
                  <PhoneIcon className="h-4 w-4 mr-1" />
                  +7 (900) 123-45-67
                </a>
                <button
                  onClick={() => {
                    openModal();
                    setIsMenuOpen(false);
                  }}
                  className="w-full bg-gradient-to-r from-[#FF7A00] to-[#FFA447] text-white px-4 py-2 rounded-2xl font-semibold"
                >
                  Заказать звонок
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Header;