import React, { useState } from 'react';
import { Dialog, Transition } from '@headlessui/react';
import { Fragment } from 'react';
import { XMarkIcon, CheckCircleIcon, ShoppingBagIcon } from '@heroicons/react/24/outline';
import { useForm } from 'react-hook-form';
import toast from 'react-hot-toast';
import { useOrder } from '../context/OrderContext';
import { motion } from 'framer-motion';

const OrderModal = () => {
  const { isModalOpen, selectedProduct, closeModal } = useOrder();
  const [showSuccess, setShowSuccess] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { register, handleSubmit, formState: { errors }, reset } = useForm();

  const onSubmit = async (data) => {
    setIsSubmitting(true);
    try {
      // Симуляция отправки заказа
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      console.log('Order data:', { ...data, product: selectedProduct });
      
      setShowSuccess(true);
      reset();
      
      toast.success('Заказ успешно отправлен!');
      
      setTimeout(() => {
        setShowSuccess(false);
        closeModal();
      }, 4000);
      
    } catch (error) {
      toast.error('Произошла ошибка при отправке заказа');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setShowSuccess(false);
    closeModal();
    reset();
  };

  return (
    <Transition appear show={isModalOpen} as={Fragment}>
      <Dialog as="div" className="relative z-50" onClose={handleClose}>
        <Transition.Child
          as={Fragment}
          enter="ease-out duration-300"
          enterFrom="opacity-0"
          enterTo="opacity-100"
          leave="ease-in duration-200"
          leaveFrom="opacity-100"
          leaveTo="opacity-0"
        >
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" />
        </Transition.Child>

        <div className="fixed inset-0 overflow-y-auto">
          <div className="flex min-h-full items-center justify-center p-4 text-center">
            <Transition.Child
              as={Fragment}
              enter="ease-out duration-300"
              enterFrom="opacity-0 scale-95"
              enterTo="opacity-100 scale-100"
              leave="ease-in duration-200"
              leaveFrom="opacity-100 scale-100"
              leaveTo="opacity-0 scale-95"
            >
              <Dialog.Panel className="w-full max-w-md transform overflow-hidden rounded-3xl bg-[#1E1B1B] border border-[#FF7A00]/30 p-8 text-left align-middle shadow-2xl shadow-[#FF7A00]/20 transition-all">
                {!showSuccess ? (
                  <>
                    {/* Заголовок */}
                    <div className="flex justify-between items-center mb-6">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-gradient-to-r from-[#FF7A00] to-[#FFA447] rounded-2xl flex items-center justify-center mr-3">
                          <ShoppingBagIcon className="h-5 w-5 text-white" />
                        </div>
                        <Dialog.Title className="text-2xl font-bold text-[#F5F5F5]">
                          Оформить заказ
                        </Dialog.Title>
                      </div>
                      <button
                        onClick={handleClose}
                        className="text-[#BDBDBD] hover:text-[#FF7A00] transition-colors p-2 hover:bg-[#FF7A00]/10 rounded-full"
                      >
                        <XMarkIcon className="h-6 w-6" />
                      </button>
                    </div>

                    {/* Информация о товаре */}
                    {selectedProduct && (
                      <motion.div 
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="mb-6 p-4 bg-gradient-to-r from-[#FF7A00]/10 to-[#FFA447]/10 rounded-2xl border border-[#FF7A00]/20"
                      >
                        <div className="flex items-center">
                          <img 
                            src={selectedProduct.image} 
                            alt={selectedProduct.name}
                            className="w-16 h-16 rounded-xl object-cover mr-4"
                          />
                          <div className="flex-1">
                            <div className="font-semibold text-[#F5F5F5] mb-1">
                              {selectedProduct.name}
                            </div>
                            <div className="text-2xl font-bold text-[#FF7A00]">
                              {selectedProduct.price} ₽
                            </div>
                            {selectedProduct.oldPrice && (
                              <div className="text-sm text-[#BDBDBD] line-through">
                                {selectedProduct.oldPrice} ₽
                              </div>
                            )}
                          </div>
                        </div>
                      </motion.div>
                    )}

                    {/* Форма */}
                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                      {/* Имя */}
                      <div>
                        <label className="block text-[#F5F5F5] font-semibold mb-2">
                          Ваше имя *
                        </label>
                        <input
                          {...register('name', { 
                            required: 'Имя обязательно',
                            minLength: { value: 2, message: 'Минимум 2 символа' }
                          })}
                          className="w-full px-4 py-3 bg-[#121212] border border-[#FF7A00]/30 rounded-2xl text-[#F5F5F5] focus:outline-none focus:border-[#FF7A00] focus:ring-2 focus:ring-[#FF7A00]/20 transition-all"
                          placeholder="Введите ваше имя"
                        />
                        {errors.name && (
                          <motion.p 
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="text-red-400 text-sm mt-1"
                          >
                            {errors.name.message}
                          </motion.p>
                        )}
                      </div>

                      {/* Телефон */}
                      <div>
                        <label className="block text-[#F5F5F5] font-semibold mb-2">
                          Телефон *
                        </label>
                        <input
                          {...register('phone', {
                            required: 'Телефон обязателен',
                            pattern: {
                              value: /^[+]?[0-9\s\-\(\)]+$/,
                              message: 'Неверный формат телефона'
                            },
                            minLength: { value: 10, message: 'Минимум 10 цифр' }
                          })}
                          placeholder="+7 (900) 123-45-67"
                          className="w-full px-4 py-3 bg-[#121212] border border-[#FF7A00]/30 rounded-2xl text-[#F5F5F5] focus:outline-none focus:border-[#FF7A00] focus:ring-2 focus:ring-[#FF7A00]/20 transition-all"
                        />
                        {errors.phone && (
                          <motion.p 
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="text-red-400 text-sm mt-1"
                          >
                            {errors.phone.message}
                          </motion.p>
                        )}
                      </div>

                      {/* Email */}
                      <div>
                        <label className="block text-[#F5F5F5] font-semibold mb-2">
                          Email (необязательно)
                        </label>
                        <input
                          {...register('email', {
                            pattern: {
                              value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                              message: 'Неверный формат email'
                            }
                          })}
                          type="email"
                          placeholder="your@email.com"
                          className="w-full px-4 py-3 bg-[#121212] border border-[#FF7A00]/30 rounded-2xl text-[#F5F5F5] focus:outline-none focus:border-[#FF7A00] focus:ring-2 focus:ring-[#FF7A00]/20 transition-all"
                        />
                        {errors.email && (
                          <motion.p 
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="text-red-400 text-sm mt-1"
                          >
                            {errors.email.message}
                          </motion.p>
                        )}
                      </div>

                      {/* Комментарий */}
                      <div>
                        <label className="block text-[#F5F5F5] font-semibold mb-2">
                          Комментарий к заказу
                        </label>
                        <textarea
                          {...register('comment')}
                          rows={3}
                          placeholder="Укажите модель телефона, цвет чехла или другие пожелания..."
                          className="w-full px-4 py-3 bg-[#121212] border border-[#FF7A00]/30 rounded-2xl text-[#F5F5F5] focus:outline-none focus:border-[#FF7A00] focus:ring-2 focus:ring-[#FF7A00]/20 transition-all resize-none"
                        />
                      </div>

                      {/* Согласие */}
                      <div className="mb-6">
                        <label className="flex items-start">
                          <input
                            {...register('consent', { required: 'Необходимо согласие' })}
                            type="checkbox"
                            className="mt-1 mr-3 w-4 h-4 text-[#FF7A00] bg-[#121212] border-[#FF7A00]/30 rounded focus:ring-[#FF7A00] focus:ring-2"
                          />
                          <span className="text-sm text-[#BDBDBD] leading-relaxed">
                            Я согласен на обработку персональных данных в соответствии с{' '}
                            <a href="#" className="text-[#FF7A00] underline hover:text-[#FFA447]">
                              Политикой конфиденциальности
                            </a>
                          </span>
                        </label>
                        {errors.consent && (
                          <motion.p 
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="text-red-400 text-sm mt-1"
                          >
                            {errors.consent.message}
                          </motion.p>
                        )}
                      </div>

                      {/* Кнопка отправки */}
                      <button
                        type="submit"
                        disabled={isSubmitting}
                        className="w-full bg-gradient-to-r from-[#FF7A00] to-[#FFA447] text-white py-4 rounded-2xl font-bold text-lg hover:shadow-2xl hover:shadow-[#FF7A00]/40 transition-all duration-300 transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
                      >
                        {isSubmitting ? (
                          <div className="flex items-center justify-center">
                            <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
                            Отправляем заказ...
                          </div>
                        ) : (
                          'Оформить заказ'
                        )}
                      </button>
                    </form>

                    {/* Дополнительная информация */}
                    <div className="mt-6 p-4 bg-[#121212] rounded-2xl border border-[#FF7A00]/20">
                      <p className="text-sm text-[#BDBDBD] text-center">
                        🔒 Ваши данные защищены и не передаются третьим лицам
                      </p>
                    </div>
                  </>
                ) : (
                  /* Экран успеха */
                  <motion.div 
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="text-center py-8"
                  >
                    <motion.div
                      initial={{ scale: 0 }}
                      animate={{ scale: 1 }}
                      transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
                      className="w-20 h-20 bg-gradient-to-r from-green-500 to-green-600 rounded-full flex items-center justify-center mx-auto mb-6"
                    >
                      <CheckCircleIcon className="h-10 w-10 text-white" />
                    </motion.div>
                    
                    <motion.h3 
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.4 }}
                      className="text-3xl font-bold text-[#F5F5F5] mb-4"
                    >
                      Спасибо за заказ!
                    </motion.h3>
                    
                    <motion.div
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.6 }}
                      className="space-y-4"
                    >
                      <p className="text-[#BDBDBD] text-lg leading-relaxed">
                        Ваша заявка принята и передана менеджеру
                      </p>
                      <div className="bg-gradient-to-r from-[#FF7A00]/10 to-[#FFA447]/10 p-4 rounded-2xl border border-[#FF7A00]/20">
                        <p className="text-[#F5F5F5] font-semibold mb-2">
                          Что дальше?
                        </p>
                        <ul className="text-sm text-[#BDBDBD] space-y-1 text-left">
                          <li>✓ Менеджер свяжется с вами в течение 15 минут</li>
                          <li>✓ Уточнит детали заказа и способ доставки</li>
                          <li>✓ Отправит товар в день заказа</li>
                        </ul>
                      </div>
                    </motion.div>
                  </motion.div>
                )}
              </Dialog.Panel>
            </Transition.Child>
          </div>
        </div>
      </Dialog>
    </Transition>
  );
};

export default OrderModal;